TLM.f("Sancti/09-27",{"officium":"S. Cosmæ et Damiani Martyrum","rule":["vide C3a;","Gloria"],"fallback":"Commune/C3a","from":{"Tractus":"Commune/C3a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15 et 14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent pópuli, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent pópuli, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, qui sanctórum Mártyrum tuórum Cosmæ et Damiáni natalítia cólimus, a cunctis malis imminéntibus, eórum intercessiónibus, liberémur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 5:16-20"},{"k":"text","la":"Iusti autem in perpétuum vivent, et apud Dóminum est merces eórum, et cogitátio illórum apud Altíssimum. Ideo accípient regnum decóris, et diadéma speciéi de manu Dómini: quóniam déxtera sua teget eos, et bráchio sancto suo deféndet illos. Accípiet armatúram zelus illíus, et armábit creatúram ad ultiónem inimicórum. Induet pro thoráce justítiam, et accípiet pro gálea judícium certum. Sumet scutum inexpugnábile æquitátem."}],"Graduale":[{"k":"ref","la":"Ps 33:18-19"},{"k":"text","la":"Clamavérunt justi, et Dóminus exaudívit eos: et ex ómnibus tribulatiónibus eórum liberávit eos."},{"k":"text","la":"Juxta est Dóminus his, qui tribuláto sunt corde: et húmiles spíritu salvabit. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secuta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Ps 123:7-8"},{"k":"text","la":"Anima nostra, sicut passer, erépta est de láqueo venántium."},{"k":"text","la":"Láqueus contrítus est, et nos liberáti sumus: adjutórium nostrum in nómine Dómini, qui fecit cœlum et terram.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flebant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 6:17-23"},{"k":"text","la":"In illo témpore: Descéndens Jesus de monte, stetit in loco campéstri, et turba discipulórum ejus, et multitúdo copiósa plebis ab omni Judæa, et Jerúsalem, et marítima, et Tyri, et Sidónis, qui vénerant, ut audírent eum et sanaréntur a languóribus suis. Et, qui vexabántur a spirítibus immúndis, curabántur. Et omnis turba quærébat eum tángere: quia virtus de illo exíbat, et sanábat omnes. Et ipse, elevátis óculis in discípulos suos, dicebat: Beáti, páuperes: quia vestrum est regnum Dei. Beáti, qui nunc esurítis: quia saturabímini. Beáti, qui nunc fletis: quia ridébitis. Beáti éritis, cum vos óderint hómines, et cum separáverint vos et exprobráverint, et ejécerint nomen vestrum tamquam malum, propter Fílium hóminis. Gaudéte in illa die et exsultáte: ecce enim, merces vestra multa est in cœlo."}],"Offertorium":[{"k":"ref","la":"Ps 5:12-13"},{"k":"text","la":"Gloriabúntur in te omnes, qui díligunt nomen tuum: quóniam tu, Dómine, benedíces justo: Dómine, ut scuto bonæ voluntátis tuæ coronásti nos."}],"Secreta":[{"k":"text","la":"Sanctórum tuórum nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet, et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 78:2; 78:11"},{"k":"text","la":"Posuérunt mortália servórum tuórum, Dómine, escas volatilíbus cœli, carnes Sanctórum tuórum béstiis terræ: secúndum magnitúdinem bráchii tui pósside fílios morte punitórum."}],"Postcommunio":[{"k":"text","la":"Prótegat, quǽsumus, Dómine, pópulum tuum et participátio cœléstis indúlta convívii, et deprecátio colláta Sanctórum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"81e853df7532e872":{"t":"Sir 44, 15 i 14, Ps 32, 1\n(Sir 44, 15 i 14) O mudrosti svetih neka pripovijedaju narodi, a Crkva neka naviješta hvalu njihovu. Njihova imena žive kroz vjekove. (Ps 32, 1) Radujte se, pravednici, u Gospodinu, pravednicima dolikuje da ga hvale.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 44, 15 i 14) O mudrosti svetih neka pripovijedaju narodi, a Crkva neka naviješta hvalu njihovu. Njihova imena žive kroz vjekove.","kn":"(Crkv. 44, 15, 14). Mudrost svetih neka pripovijedaju naroidi i Crkva neka oglasuje slavu njihovu; imena će njihova živjeti u vjekovječne vjekove.’ (Ps 32, 1) Radujte se, pravednici, u Gospodinu; slavite Gospodina s pjesmom! Slava Ocu... Mudrost . . .","knRef":"Kniewald 1942, str. 798–799 (snimka 400) (OCR)"},"86788076a901ea56":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da se mi koji slavimo rođendan svetih mučenika tvojih Kuzme i Damjana po njihovu zagovoru izbavimo od svih zala koja nam prijete.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, svemoigući Bože, da nas, koji štujemo blagdan svetih mučenika Tvojih Kuzme i Damjana, njihov zagovor izbavi od svih zala, koja nam prijete, po G. n.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"},"79e56af343e4528e":{"t":"Mudr 5, 16-20\nČitanje knjige Mudrosti. Pravednici će vječno živjeti. U Gospodinu je njihova plaća i Svevišnji se brine za njih. Od Gospodina će dobiti divno kraljevstvo i krasan vijenac, jer će ih on zakriliti svojom desnicom i obraniti svojom snagom. U svojoj će se revnosti prihvatiti oružja i naoružat će svoje, da bi se osvetio neprijateljima. Pravednost će obući kao oklop, a stalna pravda bit će mu kao kaciga i pokrit će se pravednošću kao neprobojnim štitom.","kn":"Čitanje Knjige mudrosti (5, 16-20). Pravednici će vječno živjeti i u Gospodina je njihova plaća i za njih se brine Svevišnji. Zato će od Gospodina dobiti kraljevsko odličje i divan vijenac, jer će ih ziikriliti svo-jom desnicom i obraniti svojom svetom mišicom. U svojoj će revnosti prihvatiti za oružje i svoje će naoružati, da se osveti neprijateljima. Odjenut će pravednost kao oklop i za kacigu do-bit će tvrdu pravdu i pokrit će se pravednošću kao nesavladivim štitom.","knRef":"Kniewald 1942, str. 800–801 (snimka 401) (OCR)"},"416e223baaa87138":{"t":"Ps 33, 18-19\nZavapiše pravednici i Gospodin ih usliša, i izbavi ih iz svih nevolja njihovih. Gospodin je blizu onima koji su skrušena srca. On spašava ponizne duhom.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nOvo je pravo bratstvo koje je pobijedilo opačine svijeta, slijedilo je Krista i zadobilo slavimo nebesko kraljevstvo. <i>Aleluja</i>.","kn":"<i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 33, 18, 19). Zavapiše pravednici i Gospodin ih je uslišao i izbavio ih je od svih nevolja. Blizu je Gospodin onima, koji su skrušena srca i spasit će one, koji su ponizni duhorn, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"527f2ba098c01d5f":{"t":"Lk 6, 17-23\nSlijedi sveto Evanđelje po Luki. U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s mnoštvom svojih učenika i vrlo mnogo ljudi iz čitave Judeje, Jeruzalema, Primorja, Tira i Sidona, koji su došli da ga čuju i da se izliječe od svojih bolesti. I ozdravljali su oni koje su mučili nečisti duhovi. I sav ga se svijet htio dotaknuti, jer je iz njega izlazila moć, i sve je liječio. On podigne oči prema svojim učenicima i reče: Blago vama siromasima, jer je vaše Božje kraljevstvo. Blago vama koji sada gladujete, jer ćete se nasititi. Blago vama kada vas ljudi mrze i odbace, pogrde i prezru kao nečasne radi Sina Čovječjega. Radujte se i veselite u taj dan, jer je velika vaša plaća na nebu!","kn":"t Slijedi sveto evanđelje po Luki (6, 17-23). U ono vrijeme siđe Isus s gore, zaustavi se na ravnici s četom svojih učenika i vrlo mnogo ljudi iz sve Judeje i Jeruzalema i primorja i Tira i Sidona, koji su došli da ga čuju i liječe se od svojih bolesti. I ozdravljali su oni, koje su mučili nečisti duhovi. I sav je svijet htio da ga se dotakne, jer je iz njega Izlazila moć i liječio je sve. A o.n podigne^ oči na svoje učenike i reče: Blago vama siromasima, jer je vaše kraljevstvo nebesko. Blago vama, koji sada gladujete, jer ćete se nasltiti. Blago vama, koji sada plačete, jer ćete se smijati. Blago vama, kad vas ljudi mrze i odbace vas, pogrde i prezru kao nečasne radi Sina čovječjega. Radujte se^ onoga dana i veselite, jer je velika vaša plaća na nebu.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"f18e3b3e275ba7b6":{"t":"Ps 5, 12-13\nDičit će se tobom svi koji ljube ime tvoje, jer ti blagoslivljaš pravednika, Gospodine, tvoja nas dobrota kao štit brani.","kn":"(Ps. 5, 12, 13). Đičit će se Tobom svi, koji ljube ime Tvoje, jer Ti blagosivaš pravednika i zaklanjaš nas milošću svojom kao štitom. Gospodine.","knRef":"Kniewald 1942, str. 610–611 (snimka 306) (OCR)"},"ce1442a36f108cca":{"t":"Neka nam, Gospodine, bude u pomoći pobožna molitva tvojih svetih i neka nam preporuči naše darove i zadobije tvoje oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Đa nam ne preostane, Gospodine, pobožna molitva svetih Tvojih, koja TI i darove naše omiUla, i Tvoje nam proštenje vazda dostizavala. Po G. n.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"f96880bba65d16dc":{"t":"Ps 78, 2 i 11\nBacili su mrtva tjelesa slugu tvojih, Gospodine, za hranu pticama nebeskim, tjelesa svetih tvojih zvjerima zemaljskim. Desnicom svojom spasi sinove osuđenih na smrt.","kn":"(Ps. 78, 2).' Baciše trupla slugu Tvojih Gospodine, za jelo pticama nebeskim, tijela svetih Tvojih zvijerima zemaljskim; snagom mišice svoje spasi osuđene na smrt.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"},"992d3f67cca25f40":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, neka štiti tvoj narod sudjelovanje u nebeskoj gozbi koju si mu udijelio i zajednička molitva svetih.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Poklonjeno učestvovanje u nebeskoj gozbi i prinesene molitve Tvojih svetaca branile, molimo, Gospodine, narod Tvoj, po G. n.","knRef":"Kniewald 1942, str. 718–719 (snimka 360) (OCR)"}}});
